// Pure pipeline test (fast, exact):
[Fact]
public void TopPerGroup_TakesThreeNewest()
{
    List<Order> orders = new List<Order>
    {
        new Order { CustomerId = 1, Date = new DateTime(2024, 1, 3) },
        new Order { CustomerId = 1, Date = new DateTime(2024, 1, 1) },
    };
    List<Order> top = orders.GroupBy(o => o.CustomerId)
        .SelectMany(g => g.OrderByDescending(o => o.Date).Take(1)).ToList();
    Assert.Single(top);
    Assert.Equal(new DateTime(2024, 1, 3), top[0].Date);
}
