// Tap probe: logs without breaking the pipeline (dev only!)
static IEnumerable<T> Tap<T>(IEnumerable<T> source, string stage, Action<string> log)
{
    int n = 0;
    foreach (T item in source) { n++; yield return item; }
    log(stage + ": " + n + " rows");
}

